begin;
select plan(47);
insert into auth.users(id,aud,role,is_anonymous,raw_user_meta_data)
select ('80000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated',true,'{}' from generate_series(1,7)n;
set local role authenticated;
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000001","is_anonymous":true}',true);

select public.create_test_band('My test leader','test1234','112233');
select set_config('test.band',public.current_band_identity()->>'band_id',true);
select set_config('test.code',public.test_band_setup_status()->>'code',true);
select is(jsonb_array_length(public.test_band_setup_status()->'members'),0,'original one-person fixture can be expanded');
select is(public.prepare_test_band()->>'error','TEST_ROSTER_INCOMPLETE','cannot seed a partial roster');
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000002","is_anonymous":true}',true);
select ok((public.begin_band_access(current_setting('test.code'),'test1234')->>'ok')::boolean,'guitar2 uses normal band password gate');
select is(public.register_test_member('guitar2','112233')->>'error','INVALID_INPUT','common demo PIN cannot match leader personal PIN');
select ok((public.register_test_member('guitar2','246810')->>'ok')::boolean,'guitar2 is a real ordinary PIN-protected member');
select is(public.test_band_setup_status(),null::jsonb,'ordinary member cannot read leader fixture controls');
select is(public.prepare_test_band()->>'error','FORBIDDEN','ordinary member cannot seed other members');
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000003',true);
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000003","is_anonymous":true}',true);
select ok((public.begin_band_access(current_setting('test.code'),'test1234')->>'ok')::boolean,'bass uses normal band password gate');
select is(public.register_test_member('bass','123456')->>'error','TEST_PIN_MISMATCH','resumed preparation must retain common demo PIN');
select ok((public.register_test_member('bass','246810')->>'ok')::boolean,'bass is a real ordinary PIN-protected member');
select is(public.test_band_setup_status(),null::jsonb,'ordinary member cannot read leader fixture controls');
select is(public.prepare_test_band()->>'error','FORBIDDEN','ordinary member cannot seed other members');
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000004',true);
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000004","is_anonymous":true}',true);
select ok((public.begin_band_access(current_setting('test.code'),'test1234')->>'ok')::boolean,'drums uses normal band password gate');
select ok((public.register_test_member('drums','246810')->>'ok')::boolean,'drums is a real ordinary PIN-protected member');
select is(public.test_band_setup_status(),null::jsonb,'ordinary member cannot read leader fixture controls');
select is(public.prepare_test_band()->>'error','FORBIDDEN','ordinary member cannot seed other members');
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000005',true);
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000005","is_anonymous":true}',true);
select ok((public.begin_band_access(current_setting('test.code'),'test1234')->>'ok')::boolean,'vocal uses normal band password gate');
select ok((public.register_test_member('vocal','246810')->>'ok')::boolean,'vocal is a real ordinary PIN-protected member');
select is(public.test_band_setup_status(),null::jsonb,'ordinary member cannot read leader fixture controls');
select is(public.prepare_test_band()->>'error','FORBIDDEN','ordinary member cannot seed other members');
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000001","is_anonymous":true}',true);

select ok((public.prepare_test_band()->>'ok')::boolean,'leader prepares atomic five-person round');
select set_config('test.round',(select id::text from public.planning_rounds where band_id=current_setting('test.band')::uuid and status in ('collecting','ready')),true);
select is((select count(*)::int from public.round_participants where round_id=current_setting('test.round')::uuid),5,'five actual participants in fixed roster');
select is((select count(*)::int from public.round_participants where round_id=current_setting('test.round')::uuid and part_key_snapshot='기타'),2,'duplicate guitar part is represented twice');
select is((select count(*)::int from public.round_submissions where round_id=current_setting('test.round')::uuid and status='pending'),0,'all five schedules are submitted');
select is((select count(*)::int from public.round_submissions where round_id=current_setting('test.round')::uuid and status='none'),1,'drummer explicitly has no unavailable dates');
select is((select count(distinct skill)::int from public.band_members where band_id=current_setting('test.band')::uuid),3,'fixture has differing skill levels');
select set_config('test.a',(select id::text from public.songs where band_id=current_setting('test.band')::uuid and title like '[테스트 A]%'),true);
select set_config('test.b',(select id::text from public.songs where band_id=current_setting('test.band')::uuid and title like '[테스트 B]%'),true);
select set_config('test.c',(select id::text from public.songs where band_id=current_setting('test.band')::uuid and title like '[테스트 C]%'),true);
select set_config('test.d',(select id::text from public.songs where band_id=current_setting('test.band')::uuid and title like '[테스트 D]%'),true);
select is((select count(*)::int from public.song_votes where round_id=current_setting('test.round')::uuid and song_id=current_setting('test.a')::bigint and choice='yes'),5,'A has all five yes votes');
select is((select count(*)::int from public.song_votes where round_id=current_setting('test.round')::uuid and song_id=current_setting('test.b')::bigint),4,'B has four votes and leader pending');
select is((select count(*)::int from public.song_votes where round_id=current_setting('test.round')::uuid and song_id=current_setting('test.c')::bigint and choice='yes'),3,'C has only three yes votes below threshold four');
select is((select count(*)::int from public.song_difficulties where song_id=current_setting('test.a')::bigint),4,'A has all four distinct part difficulties');
select is((select count(*)::int from public.song_difficulties where song_id=current_setting('test.d')::bigint),0,'D remains missing difficulty');
select lives_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,(now() at time zone 'Asia/Seoul')::date,array[current_setting('test.a')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'A finalizes with all five attending');
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,(now() at time zone 'Asia/Seoul')::date+1,array[current_setting('test.a')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'P0001','PARTIAL_ACK_REQUIRED','partial date needs acknowledgment');
select lives_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,(now() at time zone 'Asia/Seoul')::date+1,array[current_setting('test.a')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),true)$$,'acknowledged partial date finalizes');
select is((select attendee_count from public.confirmed_plans where band_id=current_setting('test.band')::uuid and rehearsal_date=(now() at time zone 'Asia/Seoul')::date+1),3,'tomorrow has three attendees out of five');
select ok((public.prepare_test_band()->>'ok')::boolean,'completed preparation is idempotent');
select is((select id::text from public.planning_rounds where band_id=current_setting('test.band')::uuid and status in ('collecting','ready')),current_setting('test.round'),'repeat does not replace user test round');
select set_config('test.demo_member',(select id::text from public.band_members where band_id=current_setting('test.band')::uuid and user_id='80000000-0000-4000-8000-000000000002'),true);
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000006',true);
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000006","is_anonymous":true}',true);

select ok((public.begin_band_access(current_setting('test.code'),'test1234')->>'ok')::boolean,'separate device enters code/password gate');
select ok((public.member_pin_login(current_setting('test.demo_member')::uuid,'246810')->>'ok')::boolean,'separate device logs into demo profile using demo PIN');
select is(public.current_band_identity()->'member'->>'role','member','demo login has ordinary role');
select throws_ok($$select public.update_member_skill((select id from public.band_members where band_id=current_setting('test.band')::uuid and role='leader'),5::smallint)$$,'P0001','FORBIDDEN','demo cannot manage leader');
select lives_ok($$select public.add_song(current_setting('test.band')::uuid,'Member song','Demo')$$,'demo can add its own band candidate');
select lives_ok($$select public.cast_vote(current_setting('test.round')::uuid,current_setting('test.b')::bigint,'no','demo edit')$$,'demo can change its own vote');
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,(now() at time zone 'Asia/Seoul')::date,array[current_setting('test.a')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'P0001','FORBIDDEN','demo cannot finalize');
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000007',true);
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000007","is_anonymous":true}',true);

select public.create_code_band('Real band','Real leader','드럼','real1234','135790','975310');
select is(public.test_band_setup_status(),null::jsonb,'real-band owner has no fixture controls');
select is(public.prepare_test_band()->>'error','FORBIDDEN','real band cannot be reseeded');
select is(public.register_test_member('bass','246810')->>'error','FORBIDDEN','no fixture password grant cannot create demo identity');
select * from finish();
rollback;
